/// Build conversational nutrition prompt (NOT for meal plans)
// Handles: meal_idea, shopping_list, advice, recipe, meal_swap (no recent plan)

try {

  // Extract inputs
  const intent      = $input.first().json.intent || "general";
  const entities    = $input.first().json.entities || {};
  const preferences = $input.first().json.preferences || {};
  const userMessage = $input.first().json.user_message || "";
  const lastAssistantMessage = $input.first().json.lastAssistantMessage || "";

  // Normalize preferences
  const diet       = preferences.diet || null;
  const cuisine    = preferences.cuisine || null;
  const allergies  = Array.isArray(preferences.allergies) ? preferences.allergies : [];
  const dislikes   = Array.isArray(preferences.dislikes)  ? preferences.dislikes  : [];
  const conditions = Array.isArray(preferences.conditions)? preferences.conditions: [];

  // Normalize entities
  const ingredients = Array.isArray(entities.ingredient)
    ? entities.ingredient
    : (entities.ingredient ? [entities.ingredient] : []);

  const dishes = Array.isArray(entities.dish)
    ? entities.dish
    : (entities.dish ? [entities.dish] : []);

  const mealType  = entities.meal_type  || null;
  const timeframe = entities.timeframe  || null;

  // Build preferences summary text
  let prefText = "";

  if (diet) prefText += ` La usuaria sigue una dieta ${diet}.`;
  if (cuisine) prefText += ` Prefiere cocina inspirada en ${cuisine}.`;
  if (allergies.length) prefText += ` Alergias: ${allergies.join(", ")}.`;
  if (dislikes.length) prefText += ` No consume: ${dislikes.join(", ")}.`;
  if (conditions.length) prefText += ` Condiciones: ${conditions.join(", ")}.`;

  // Build entity text
  let entityText = "";

  if (ingredients.length) entityText += ` Ingredientes mencionados: ${ingredients.join(", ")}.`;
  if (dishes.length) entityText += ` Platos mencionados: ${dishes.join(", ")}.`;
  if (mealType) entityText += ` Tipo de comida: ${mealType}.`;
  if (timeframe) entityText += ` Contexto temporal: ${timeframe}.`;

  //-------------------------------------------------------------
  // BUILD PROMPT
  //-------------------------------------------------------------

  let prompt = "";

  switch (intent) {

    // 🌿 MEAL IDEA
    case "meal_idea":
      prompt = `
La usuaria desea una idea de comida o menú corto.

Mensaje actual:
"${userMessage}"

${entityText}
${prefText}

Genera una respuesta breve, cálida y amistosa en español con 1 a 3 ideas adaptadas a sus preferencias.
`;
      break;

    // 🍏 SHOPPING LIST
    case "shopping_list":
      prompt = `
La usuaria solicita una lista de compras.

Mensaje actual:
"${userMessage}"

${entityText}
${prefText}

Responde con una lista clara, organizada y práctica.
No incluyas cantidades exactas a menos que la usuaria las pida.
`;
      break;

    // 💡 ADVICE
    case "advice":
      prompt = `
La usuaria solicita un consejo nutricional.

Mensaje actual:
"${userMessage}"

${entityText}
${prefText}

Da un consejo breve, práctico y amable, inspirado en culturas de longevidad.
No des consejos médicos ni de suplementos.
`;
      break;

    // 🍽 RECIPE
    case "recipe":
      prompt = `
La usuaria solicita una receta.

Mensaje actual:
"${userMessage}"

${entityText}
${prefText}

Genera una receta breve, simple y saludable, con ingredientes accesibles.
Incluye pasos cortos y claros.
`;
      break;

    // 📎 GENERAL
    case "general":
      prompt = `
El mensaje de la usuaria no coincide con una intención clara.

Mensaje actual:
"${userMessage}"

${entityText}
${prefText}

Responde de forma breve, cálida y amistosa en español.
Si hace falta información, haz una única pregunta para aclarar qué necesita.
`;
      break;

    // 🧩 FALLBACK
    default:
      prompt = `
Intención detectada: ${intent}.

Mensaje actual:
"${userMessage}"

${entityText}
${prefText}

Responde siguiendo las instrucciones del sistema.
`;
  }

  //-------------------------------------------------------------
  // Conversation context
  //-------------------------------------------------------------

  if (lastAssistantMessage) {
    prompt =
`Contexto de la conversación:

Última respuesta del asistente (solo como referencia para mantener la continuidad; NO la repitas literalmente):

"${lastAssistantMessage}"

------------------------------------------------------------

` + prompt;
  }

  //-------------------------------------------------------------
  // Return
  //-------------------------------------------------------------

  return {
    json: {
      prompt,
      intent,
      entities: {
        ...entities,
        ingredient: ingredients,
        dish: dishes
      },
      preferences: {
        diet,
        cuisine,
        allergies,
        dislikes,
        conditions
      },
      context: {
        mealType,
        timeframe
      }
    }
  };

} catch (err) {

  return {
    json: {
      prompt: `Se produjo un error técnico al procesar el mensaje. Responde en español con un mensaje breve y pide a la usuaria que intente de nuevo.`,
      intent: "error",
      entities: {},
      preferences: {}
    }
  };

}

// 🛡️ Safeguard node
// Purpose: decide IF nutrition preferences should be updated
// Identity fields (e.g. name) are intentionally ignored

const intent = $json.intent || null;
const entities = $json.entities || {};
const preferences = $json.preferences || {};

// Only nutrition-related entities trigger preference updates
const updateNeeded = Boolean(
  entities.dislike ||
  entities.allergy ||
  entities.diet ||
  entities.cuisine ||
  entities.condition
);

// NOTE:
// - entities.name is intentionally ignored
// - name updates are handled separately in Unified Merge

return {
  intent,
  entities,
  preferences,
  updateNeeded
};

// 🌿 Unified Preference Merge Node (Schema-clean, normalized)
// Handles preferences + identity (name) separately
// Assumes Detect Intent & Entities already ran

// ---------- Helpers ----------
const normalize = (v) =>
  typeof v === "string" ? v.trim().toLowerCase() : v;

const toArray = (v) =>
  Array.isArray(v) ? v : v != null ? [v] : [];

// ---------- Load current user ----------
const user = $('Get User from Supabase').first().json;

// ---------- Load current preferences ----------
const currentPrefs = user.preferences || {
  diet: null,
  cuisine: null,      // MVP: string
  dislikes: [],
  allergies: [],
  conditions: []
};

const entities = $json.entities || {};
const mergedPrefs = { ...currentPrefs };

// ---------- Merge diet (string, overwrite) ----------
if (entities.diet && typeof entities.diet === "string") {
  mergedPrefs.diet = normalize(entities.diet);
}

// ---------- Merge cuisine (string, overwrite – MVP choice) ----------
if (entities.cuisine && typeof entities.cuisine === "string") {
  mergedPrefs.cuisine = normalize(entities.cuisine);
}

// ---------- Merge allergies (array, deduped, normalized) ----------
if (entities.allergy) {
  const existing = Array.isArray(mergedPrefs.allergies)
    ? mergedPrefs.allergies.map(normalize)
    : [];

  const incoming = toArray(entities.allergy).map(normalize);

  mergedPrefs.allergies = [...new Set([...existing, ...incoming])];
}

// ---------- Merge dislikes (array, deduped, normalized) ----------
if (entities.dislike) {
  const existing = Array.isArray(mergedPrefs.dislikes)
    ? mergedPrefs.dislikes.map(normalize)
    : [];

  const incoming = toArray(entities.dislike).map(normalize);

  mergedPrefs.dislikes = [...new Set([...existing, ...incoming])];
}

// ---------- Merge conditions (array, deduped, normalized) ----------
if (entities.condition) {
  const existing = Array.isArray(mergedPrefs.conditions)
    ? mergedPrefs.conditions.map(normalize)
    : [];

  const incoming = toArray(entities.condition).map(normalize);

  mergedPrefs.conditions = [...new Set([...existing, ...incoming])];
}

// ---------- Identity: name (NO normalization, overwrite only if present) ----------
const nameUpdate =
  typeof entities.name === "string" && entities.name.trim()
    ? entities.name.trim()
    : null;

// ---------- Build Supabase update payload ----------
const updatePayload = {
  id: user.id,
  preferences: mergedPrefs
};

// Only include name if user explicitly provided it
if (nameUpdate) {
  updatePayload.name = nameUpdate;
}

// ---------- Output ----------
return {
  json: {
    intent: $json.intent,
    entities,
    preferences: mergedPrefs,   // ✅ canonical preferences
    name: nameUpdate || user.name || null, // for downstream convenience
    updatePayload               // Supabase-ready payload
  }
};

