// ✅ Normalize Supabase GET response for user lookup

const items = $input.all();

if (!items.length) {
  // No data at all from Supabase node
  return [{ json: {} }];
}

let data = items[0].json;

// Supabase typically returns an array of rows
if (Array.isArray(data)) {
  if (data.length === 0) {
    // Empty array → no match
    return [{ json: {} }];
  } else {
    // Return first record
    return [{ json: data[0] }];
  }
}

// Already an object (some Supabase nodes do this)
if (typeof data === 'object' && data !== null) {
  return [{ json: data }];
}

// Default fallback
return [{ json: {} }];

// ------------------------------------------------------------
// Parse Assistant Response
// Compatible with OpenAI Responses API
// ------------------------------------------------------------

let response = null;

// 1. Preferred field (many n8n versions expose this directly)
if (typeof $json.output_text === "string") {
  response = $json.output_text.trim();
}

// 2. Standard Responses API output array
if (
  !response &&
  Array.isArray($json.output)
) {
  for (const item of $json.output) {
    if (!item.content) continue;

    for (const content of item.content) {

      if (
        content.type === "output_text" &&
        typeof content.text === "string"
      ) {
        response = content.text.trim();
        break;
      }

      if (
        content.text &&
        typeof content.text === "string"
      ) {
        response = content.text.trim();
        break;
      }
    }

    if (response) break;
  }
}

// 3. Fallback (older wrappers)
if (
  !response &&
  typeof $json.response === "string"
) {
  response = $json.response.trim();
}

// 4. Final fallback
if (!response) {
  response =
    "Lo siento, ocurrió un problema al generar la respuesta.";
}

return [
  {
    json: {
      assistant_response: response
    }
  }
];

// -----------------------------
// Parse Meal Plan JSON (STRICT)
// -----------------------------

try {
  // 1. Extract the model's JSON string
  const rawContent =
    $json.choices?.[0]?.message?.content ??
    (() => { throw new Error("Missing assistant message content."); })();

  let cleaned = rawContent;

  // 2. If wrapped in quotes: JSON inside JSON → double-parse
  if (
    typeof cleaned === "string" &&
    cleaned.startsWith('"') &&
    cleaned.endsWith('"')
  ) {
    cleaned = JSON.parse(cleaned);
  }

  // 3. Parse into actual object
  const parsed = JSON.parse(cleaned);

  // 4. Validate structure
  if (!parsed || typeof parsed !== "object") {
    throw new Error("Response is not a JSON object.");
  }

  const duration = parseInt(parsed.duration_days);
  const days = parsed.days;

  if (!duration || duration < 1) {
    throw new Error("Missing or invalid duration_days.");
  }

  if (!Array.isArray(days) || days.length === 0) {
    throw new Error("Missing or invalid 'days' array.");
  }

  // 5. Cap to 7 days
  const maxDays = 7;
  const duration_days = Math.min(duration, maxDays);

  const trimmedDays = days.slice(0, duration_days);

  // 6. Normalize meals
  const normalizedDays = trimmedDays.map((d, idx) => {
    const meals = d.meals || {};

    function normalizeMeal(m) {

      if (!m) return {};

      return {

        title: m.title || "",

        description: m.description || "",

        calories: m.calories ?? null,

        macros: {

          protein: m.macros?.protein ?? null,
          carbs: m.macros?.carbs ?? null,
          fat: m.macros?.fat ?? null

        },

        recipe: {

          ingredients:
            m.recipe?.ingredients ?? [],

          steps:
            m.recipe?.steps ?? []

        }

      };

    }

    const snacks = Array.isArray(meals.snacks)
      ? meals.snacks.map(s => ({
          title: s.title || "",
          calories: s.calories ?? null
        }))
      : [];

    return {
      day: d.day || idx + 1,
      meals: {
        breakfast: normalizeMeal(meals.breakfast),
        lunch: normalizeMeal(meals.lunch),
        dinner: normalizeMeal(meals.dinner),
        snacks
      }
    };
  });

  // 7. Final normalized JSON
  const mealPlan = {
    duration_days,
    days: normalizedDays
  };

  return [
    {
      json: {
        success: true,
        mealPlan
      }
    }
  ];

} catch (error) {
  return [
    {
      json: {
        success: false,
        message:
          "Hubo un problema al interpretar el plan, por favor intenta de nuevo 😊",
        error: error.message,
        raw: $json
      }
    }
  ];
}

// Version if Twilio uses {{ $json.message }}
return [
  {
    json: {
      message: "Ups 😅 hubo un problema al preparar tu plan. Por favor, inténtalo otra vez en un momento 🙏"
    }
  }
];

