const keywordPatterns = [
  /^ok$/i, /^oki$/i, /^okey$/i,
  /^si$/i, /^sí$/i, /^sip$/i, /^sii+$/i,
  /^claro$/i, /^dale$/i, /^sale$/i, /^va+$/i,
  /^sigue$/i, /^continua$/i, /^continúa$/i,
  /^adelante$/i, /^procede$/i,
  /^mas info$/i, /^más info$/i,
  /^mas detalles$/i, /^más detalles$/i,
  /^dime mas$/i, /^dime más$/i,
  /^y eso\??$/i,
  /^\?y$/i,
  /^\👍$|^\👌$|^\🙏$|^\🙌$|^\😉$/
];

const containsKeyword = keywordPatterns.some(re => re.test(userMessage));

// --- 4. BLOCK OBVIOUS NEW INTENTS ---
const looksLikeNewIntent = /(plan|receta|lista|cena|comida|desayuno|almuerzo|ideas|compras)/i.test(userMessage);

// --- 5. FINAL DECISION ---
const isFollowUp =
  containsKeyword ||
  (isShort && !looksLikeNewIntent);

return {
  isFollowUp,
  userMessage,
  reason: containsKeyword
    ? "keyword-match"
    : isShort && !looksLikeNewIntent
      ? "short-vague"
      : "standalone"
};

const data = $json;

// --- SAFETY FALLBACKS ---
const rawMessage = data.user_message || "";
const intent = data.intent || "unknown";
