// -----------------------------
// Parse Meal Plan JSON Weekly Update (STRICT)
// -----------------------------

try {
  // 1. Extract the model's JSON string
  const rawContent =
    $json.choices?.[0]?.message?.content ??
    (() => { throw new Error("Missing assistant message content."); })();

  let cleaned = rawContent;

  // 2. If wrapped in quotes: JSON inside JSON → double-parse
  if (
    typeof cleaned === "string" &&
    cleaned.startsWith('"') &&
    cleaned.endsWith('"')
  ) {
    cleaned = JSON.parse(cleaned);
  }

  // 3. Parse into actual object
  const parsed = JSON.parse(cleaned);

  // 4. Validate structure
  if (!parsed || typeof parsed !== "object") {
    throw new Error("Response is not a JSON object.");
  }

  const duration =
    parseInt(parsed.duration_days || 7);

  const days = parsed.days;

  if (duration < 1) {
    throw new Error("Invalid duration_days.");
  }

  if (!Array.isArray(days) || days.length === 0) {
    throw new Error("Missing or invalid 'days' array.");
  }

  // 5. Cap to 7 days
  const maxDays = 7;
  const duration_days = Math.min(duration, maxDays);

  const trimmedDays = days.slice(0, duration_days);

  // 6. Normalize meals
  const normalizedDays = trimmedDays.map((d, idx) => {
    const meals = d.meals || {};

    function normalizeMeal(m) {

      if (!m) return {};

      return {

        title: m.title || "",

        description: m.description || "",

        calories: m.calories ?? null,

        macros: {

          protein: m.macros?.protein ?? null,
          carbs: m.macros?.carbs ?? null,
          fat: m.macros?.fat ?? null

        },

        recipe: {

          ingredients:
            m.recipe?.ingredients ?? [],

          steps:
            m.recipe?.steps ?? []

        }

      };

    }

    const snacks = Array.isArray(meals.snacks)
      ? meals.snacks
      : [];

    return {
      day: d.day || idx + 1,
      meals: {
        breakfast: normalizeMeal(meals.breakfast),
        lunch: normalizeMeal(meals.lunch),
        dinner: normalizeMeal(meals.dinner),
        snacks
      }
    };
  });

  // 7. Final normalized JSON
  const mealPlan = {
    duration_days,
    days: normalizedDays
  };

  return [
    {
      json: {

        success: true,

        user_id:
            $('Build Weekly Update Prompt')
                .first()
                .json
                .user_id,

        mealPlan

      }
    }
  ];

} catch (error) {
  return [
    {
      json: {
        success: false,
        message:
          "Hubo un problema al interpretar el plan, por favor intenta de nuevo 😊",
        error: error.message,
        raw: $json
      }
    }
  ];
}

const generationContext = $('Build Weekly Update Prompt').first().json;

return [{
  json: {
    ...$json,
    program_id: generationContext.program_id || null,
    week_id: generationContext.week_id || null
  }
}];

